 *
 * Run by SQL Agent job "Budget Sync Data" (enabled) every 5 minutes, as steps
 * 2 and 3 after InsertBudgetFromHANA: `... 1` then `... 2` (companies 1 and 2
 * only; company 3 is never processed). Not called from JSAP C#.
 */
CREATE PROCEDURE [bud].[jsProcessAllUsersBudgetApprovals]      @company INT = 2  AS  BEGIN      SET NOCOUNT ON;            -- Declare variables      DECLARE @userId INT;      DECLARE @userName VARCHAR(100);            -- Create a temporary table to store user information      CREATE TABLE #UserList (          userId INT,          userName VARCHAR(100)      );            -- Get all active users for the specified company      INSERT INTO #UserList (userId, userName)      SELECT u.userId AS userId, u.loginUser AS userName      FROM jsUser AS u      INNER JOIN jsUserCompany AS uc ON uc.userId = u.userId      WHERE uc.companyId = @company;            -- Process each user      DECLARE user_cursor CURSOR FOR       SELECT userId, userName FROM #UserList;            OPEN user_cursor;      FETCH NEXT FROM user_cursor INTO @userId, @userName;            WHILE @@FETCH_STATUS = 0      BEGIN          -- Log the processing start for this user (optional)          INSERT INTO bud.jsProcessLog (ProcessTime, UserId, UserName, ProcessType, Message)          VALUES (GETDATE(), @userId, @userName, 'BudgetApproval', 'Started processing budget approvals');                    BEGIN TRY              -- Create a table variable to store query data for current user              DECLARE @UserQueryData dbo.QueryTableType;                            -- Get queries for current user and store them in the table variable              INSERT INTO @UserQueryData (userId, stageId, tempId, queryId, query, approvalId, approvalName)              EXEC [dbo].[jsGetQueries] @userId, @company, 5;                            -- Execute budget queries for this user if any data exists              IF EXISTS (SELECT 1 FROM @UserQueryData)              BEGIN                  -- Execute selected queries and insert data into TempBudgetResults                  EXEC [bud].[jsExecuteBudgetQueries] @inputTable = @UserQueryData;                                    -- Log successful processing                  INSERT INTO bud.jsProcessLog (ProcessTime, UserId, UserName, ProcessType, Message)                  VALUES (GETDATE(), @userId, @userName, 'BudgetApproval', 'Successfully processed budget approvals');              END              ELSE              BEGIN                  -- Log that no queries were found for this user                  INSERT INTO bud.jsProcessLog (ProcessTime, UserId, UserName, ProcessType, Message)                  VALUES (GETDATE(), @userId, @userName, 'BudgetApproval', 'No pending budget approvals found');              END       DELETE FROM @UserQueryData;          END TRY          BEGIN CATCH              -- Log any errors that occur during processing              INSERT INTO bud.jsProcessLog (ProcessTime, UserId, UserName, ProcessType, Message)              VALUES (GETDATE(), @userId, @userName, 'BudgetApproval',                      'Error processing budget approvals: ' + ERROR_MESSAGE());          END CATCH                    -- Move to the next user          FETCH NEXT FROM user_cursor INTO @userId, @userName;      END            CLOSE user_cursor;      DEALLOCATE user_cursor;            -- Clean up      DROP TABLE #UserList;            -- Return success message      SELECT 'Successfully processed budget approvals for all users in company ' + CAST(@company AS VARCHAR) AS Result;  END
